style.css:
@-moz-document url-prefix("https://chatgpt.com/") {
/* Fondo y texto general */
    body {
        background-color: #000000; /* Negro AMOLED puro */
        color: #e0e0e0; /* Texto claro */
        transition: background-color 0.3s ease, color 0.3s ease;
    }

    .main-container {
        background-color: #000000; /* Negro AMOLED puro */
        color: #e0e0e0; /* Texto claro */
        transition: background-color 0.3s ease, color 0.3s ease;
    }

    .chat-container {
        background-color: #000000; /* Negro AMOLED puro */
        color: #e0e0e0; /* Texto claro */
        transition: background-color 0.3s ease, color 0.3s ease;
    }

    .duration-500 {
        background-color: #000000; /* Negro AMOLED puro */
        color: #e0e0e0;
        transition: background-color 0.3s ease, color 0.3s ease;
    }

    #composer-background {
        background-color: #000000; /* Negro AMOLED puro */
        color: #e0e0e0;
        transition: background-color 0.3s ease, color 0.3s ease;
    }

    .no-draggable-children {
        background-color: #000000; /* Negro AMOLED puro */
        color: #e0e0e0;
        transition: background-color 0.3s ease, color 0.3s ease;
    }

    .items-start > .flex {
        background-color: #000000; /* Negro AMOLED puro */
        color: #e0e0e0;
        transition: background-color 0.3s ease, color 0.3s ease;
    }

    .group\/sidebar {
        background-color: #000000; /* Negro AMOLED puro */
        color: #e0e0e0;
        transition: background-color 0.3s ease, color 0.3s ease;
    }

    .w-full:nth-child(21) .absolute:nth-child(1) > .flex:nth-child(1) {
        background-color: #000000; /* Negro AMOLED puro */
        color: #e0e0e0;
        transition: background-color 0.3s ease, color 0.3s ease;
    }

    .w-full:nth-child(21) .contain-inline-size:nth-child(1) > .flex:nth-child(1) {
        background-color: #000000; /* Negro AMOLED puro */
        color: #e0e0e0;
        transition: background-color 0.3s ease, color 0.3s ease;
    }

    .w-full:nth-child(20) .min-h-8 > .flex > .relative {
        background-color: #000000; /* Negro AMOLED puro */
        color: #e0e0e0;
        transition: background-color 0.3s ease, color 0.3s ease;
    }

    .w-full:nth-child(20) .p-2:nth-child(1) {
        background-color: #000000; /* Negro AMOLED puro */
        color: #e0e0e0;
        transition: background-color 0.3s ease, color 0.3s ease;
    }

    .relative:nth-child(1) > ol > .relative:nth-child(2) > .no-draggable > .flex {
        background-color: #000000; /* Negro AMOLED puro */
        color: #e0e0e0;
        transition: border-color 0.3s ease, background-color 0.3s ease;
    }

    .relative:nth-child(1) > ol > .relative:nth-child(2) > .no-draggable > .flex:focus,
    .relative:nth-child(1) > ol > .relative:nth-child(2) > .no-draggable > .flex.active {
        border: 2px solid #ffffff !important; /* Borde blanco cuando está seleccionado */
    }

    .mt-5:nth-child(1) > .sticky > .flex {
        background-color: #000000; /* Negro AMOLED */
        transition: background-color 0.3s ease;
    }

    div:nth-child(3) > .no-draggable {
        background-color: #000000; /* Negro AMOLED */
        transition: background-color 0.3s ease;
    }

    .items-center > .btn {
        background-color: #000000; /* Negro AMOLED */
        color: #e0e0e0 !important; /* Texto claro */
        transition: background-color 0.3s ease;
    }

    /* Caja de texto */
    textarea {
        background-color: #000000; /* Negro AMOLED puro */
        color: #e0e0e0;
        border: 1px solid #1a1a1a; /* Borde sutil */
        border-radius: 6px;
        transition: border-color 0.3s ease, background-color 0.3s ease;
    }

    textarea:focus {
        border-color: #e0e0e0; /* Borde blanco sutil */
        background-color: #000000;
    }

    .chat-input {
        background-color: #000000; /* Negro AMOLED puro */
        color: #e0e0e0;
        border: 1px solid #1a1a1a;
        border-radius: 6px;
        transition: border-color 0.3s ease, background-color 0.3s ease;
    }

    .chat-input:focus {
        border-color: #e0e0e0; /* Borde blanco sutil */
        background-color: #000000;
    }

    .message-input {
        background-color: #000000; /* Negro AMOLED puro */
        color: #e0e0e0;
        border: 1px solid #1a1a1a;
        border-radius: 6px;
        transition: border-color 0.3s ease, background-color 0.3s ease;
    }

    .message-input:focus {
        border-color: #e0e0e0; /* Borde blanco sutil */
        background-color: #000000;
    }

    /* Excepciones: Íconos y botones originales */
    textarea .icon {
        background-color: inherit;
        color: inherit;
        border: none;
        box-shadow: none;
    }

    .chat-input .icon {
        background-color: inherit;
        color: inherit;
        border: none;
        box-shadow: none;
    }

    .message-input .icon {
        background-color: inherit;
        color: inherit;
        border: none;
        box-shadow: none;
    }

    .chat-input button {
        background-color: inherit;
        color: inherit;
        border: none;
        box-shadow: none;
    }

    .message-input button {
        background-color: inherit;
        color: inherit;
        border: none;
        box-shadow: none;
    }

    .profile-button {
        background-color: inherit;
        color: inherit;
        border: none;
        box-shadow: none;
    }

    .profile-picture {
        background-color: inherit;
        color: inherit;
        border: none;
        box-shadow: none;
    }
}
